61	// gateVerdict is the answer for one overlay. File is relative to the limit, with
62	// forward slashes; Field is the YAML path of the entry, with list indices
63	// (resources[1], patches[0].path); for an inline plugin configuration it is the
64	// field of the kustomization followed by the field of the plugin
65	// (transformers[0].path), for a plugin file the field inside that file. Ref is
66	// what localRef was given.
67	type gateVerdict struct {
68		Kind                     gateKind
69		File, Field, Ref, Reason string
70	}
71	
72	// gateLimits bound what the gate reads of a repository that is not trusted.
73	type gateLimits struct {
74		// Depth is the number of levels of overlay below the first; Visited the
75		// number of distinct kustomizations read.
76		Depth, Visited int
77		// FileBytes is the size of one file; TotalBytes of every file read for one
78		// overlay.
79		FileBytes, TotalBytes int64
80	}
81	
82	// defaultGateLimits keep the gate itself cheap: YAML read into nodes costs about a
83	// hundred times the size of the file in memory, so a megabyte per file and eight
84	// for an overlay bound what a repository that is not trusted can make it spend.
85	var defaultGateLimits = gateLimits{Depth: 16, Visited: 256, FileBytes: 1 << 20, TotalBytes: 8 << 20}
