251	const (
252		// gateData: no reference (a name, a label, an inline patch, a literal).
253		gateData gateRuleKind = iota
254		// gateFile: a reference to a file, not followed.
255		gateFile
256		// gateBase: a reference to a file or to a directory with a kustomization,
257		// which is read in turn.
258		gateBase
259		// gateFileSource: a files entry of a generator, `path` or `key=path`.
260		gateFileSource
261		// gatePlugin: a generator, transformer or validator, inline or the path of a
262		// configuration file. A directory is refused: kustomize reads the resources of
263		// its kustomization as plugin configurations, which the gate does not follow.
264		gatePlugin
265		// gatePatch: a strategic merge patch, inline or a path.
266		gatePatch
267		// gateNever: a value that names a program or its arguments: always refused.
268		gateNever
269		gateList
270		gateMap
271	)
