378	// ── The walk ─────────────────────────────────────────────────────────────────
379	
380	// gate is one run of vetOverlay.
381	type gate struct {
382		ctx     context.Context //nolint:containedctx // one run of the gate, never stored
383		root    string          // the limit, absolute, symbolic links resolved
384		lim     gateLimits
385		visited map[string]bool // directories entered, by real path
386		count   int             // kustomizations read
387		read    int64           // bytes read
388		bases   []string        // the directories the kustomization being read pulls in
389		limit   string          // what the limit is called in a reason
390		cache   *gateCache
391	}
392	
393	// gateCache remembers, for the whole pass of a scan, the directories whose
394	// kustomization and everything it pulls in were judged local, so that overlays
395	// that share a base read it once. Only a verdict of OK is kept, and only once the
396	// whole overlay is OK: a directory met while a cycle was still open is not known
397	// to be fine before that. A nil cache remembers nothing.
398	type gateCache struct {
399		mu sync.Mutex
400		ok map[string]bool
401	}
402	
403	func (c *gateCache) has(real string) bool {
404		if c == nil {
405			return false
406		}
407		c.mu.Lock()
408		defer c.mu.Unlock()
409		return c.ok[real]
410	}
411	
412	func (c *gateCache) add(dirs map[string]bool) {
413		if c == nil {
414			return
415		}
416		c.mu.Lock()
417		defer c.mu.Unlock()
418		if c.ok == nil {
419			c.ok = map[string]bool{}
420		}
421		for d := range dirs {
422			c.ok[d] = true
423		}
424	}
425	
426	// gateRun is what a caller that asks about many overlays of one scan adds.
427	type gateRun struct {
428		cache *gateCache
429		// limit is how the limit of the paths is called in a reason: "the scanned
430		// folder" or "the repository" (the default).
431		limit string
432	}
433	
434	// gateSite is where a value was read: file is the file it is in (relative to
435	// the limit), dir the directory its references are relative to (the one of the
436	// kustomization, also for a plugin file), depth how far below the first overlay.
437	type gateSite struct {
438		file  string
439		dir   string
440		depth int
441	}
442	
443	func (s gateSite) remote(field, ref, reason string) gateVerdict {
444		return gateVerdict{Kind: gateRemote, File: s.file, Field: field, Ref: ref, Reason: reason}
445	}
446	
447	func (s gateSite) unchecked(field, ref, reason string) gateVerdict {
448		return gateVerdict{Kind: gateUnchecked, File: s.file, Field: field, Ref: ref, Reason: reason}
449	}
450	
451	// vetOverlay reads the overlay directory (absolute) and everything it pulls in,
452	// inside root (absolute; the gate resolves symbolic links itself).
453	func vetOverlay(ctx context.Context, root, overlay string, lim gateLimits) gateVerdict {
454		return vetOverlayIn(ctx, root, overlay, lim, gateRun{})
455	}
456	
457	// vetOverlayIn is vetOverlay for one pass of a scan.
458	func vetOverlayIn(ctx context.Context, root, overlay string, lim gateLimits, run gateRun) gateVerdict {
459		if run.limit == "" {
460			run.limit = "the repository"
461		}
462		unchecked := func(reason string) gateVerdict { return gateVerdict{Kind: gateUnchecked, Reason: reason} }
463		root, err := filepath.Abs(root)
464		if err != nil {
465			return unchecked("the limit of the paths cannot be resolved")
466		}
467		if root, err = filepath.EvalSymlinks(root); err != nil {
468			return unchecked("the limit of the paths cannot be resolved")
469		}
470		if overlay, err = filepath.Abs(overlay); err != nil {
471			return unchecked("the overlay cannot be resolved")
472		}
473		real, err := filepath.EvalSymlinks(overlay)
474		switch {
475		case isMissing(err):
476			return gateVerdict{} // kustomize reports it, and fetches nothing
477		case err != nil:
478			return unchecked("the overlay cannot be resolved")
479		case !within(root, real):
480			return unchecked("the overlay is outside " + run.limit)
481		}
482		g := &gate{ctx: ctx, root: root, lim: lim, visited: map[string]bool{}, limit: run.limit, cache: run.cache}
483		v := g.dir(real, 0)
484		if v.Kind == gateOK {
485			run.cache.add(g.visited)
486		}
487		return v
488	}
489	
490	// within reports whether p is root or below it, lexically.
491	func within(root, p string) bool {
492		rel, err := filepath.Rel(root, p)
493		return err == nil && rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator))
494	}
495	
496	// isMissing reports whether err says a path is not there (or has a file where a
497	// directory should be): nothing for kustomize to load, so nothing to fetch.
498	func isMissing(err error) bool {
499		return err != nil && (errors.Is(err, fs.ErrNotExist) || errors.Is(err, syscall.ENOTDIR))
500	}
501	
502	// rel is p relative to the limit, with forward slashes.
503	func (g *gate) rel(p string) string {
504		r, err := filepath.Rel(g.root, p)
505		if err != nil {
506			return filepath.ToSlash(p)
507		}
508		return filepath.ToSlash(r)
509	}
510	
511	// dir judges the kustomization of one directory (a real path inside the limit)
512	// and, through it, everything it pulls in. A directory with none holds nothing
513	// to follow.
514	func (g *gate) dir(real string, depth int) gateVerdict {
515		if g.visited[real] || g.cache.has(real) {
516			return gateVerdict{}
517		}
518		g.visited[real] = true
519		where := gateSite{file: g.rel(real), dir: real, depth: depth}
520		switch {
521		case g.ctx.Err() != nil:
522			return where.unchecked("", "", "the check was cancelled")
523		case depth > g.lim.Depth:
524			return where.unchecked("", "", fmt.Sprintf("overlays are nested more than %d levels deep", g.lim.Depth))
525		}
526		file, v := g.kustomizationFile(real)
527		if file == "" {
528			return v
529		}
530		if g.count++; g.count > g.lim.Visited {
531			return where.unchecked("", "", fmt.Sprintf("more than %d kustomizations are pulled in", g.lim.Visited))
532		}
533		site := gateSite{file: g.rel(file), dir: real, depth: depth}
534		bases, v := g.kustomization(file, site)
535		if v.Kind != gateOK {
536			return v
537		}
538		// The kustomization is out of memory before its bases are read in turn.
539		for _, base := range bases {
540			if v := g.dir(base, depth+1); v.Kind != gateOK {
541				return v
542			}
543		}
544		return gateVerdict{}
545	}
546	
547	// kustomization judges the file of a kustomization. The directories it pulls in
548	// are returned, not read: this function's YAML is released first.
549	func (g *gate) kustomization(file string, site gateSite) ([]string, gateVerdict) {
550		// The kustomization file may itself be a link: what is read is what it names.
551		if target, err := filepath.EvalSymlinks(file); err != nil || !within(g.root, target) {
552			return nil, site.unchecked("", "", "the kustomization file leaves "+g.limit+" through a symbolic link")
553		}
554		node, reason := g.readYAML(file)
555		if reason == reasonNoDocument {
556			reason = "the kustomization file is empty"
557		}
558		if reason != "" {
559			return nil, site.unchecked("", "", reason)
560		}
561		g.bases = nil
562		v := g.applyMap(mapOf(kustomizationRules), node, "", site, true)
563		bases := g.bases
564		g.bases = nil
565		return bases, v
566	}
567	
568	// kustomizationFile is the kustomization file of dir, "" when there is none, or a
569	// verdict when there are several.
570	func (g *gate) kustomizationFile(dir string) (string, gateVerdict) {
571		var found []string
572		for _, name := range kustomizationNames {
573			p := filepath.Join(dir, name)
574			if _, err := os.Lstat(p); err == nil {
575				found = append(found, p)
576			} else if !isMissing(err) {
577				return "", gateSite{file: g.rel(p)}.unchecked("", "", "it cannot be read ("+errReason(err)+")")
578			}
579		}
580		switch len(found) {
581		case 0:
582			return "", gateVerdict{}
583		case 1:
584			return found[0], gateVerdict{}
585		}
586		return "", gateSite{file: g.rel(found[0])}.unchecked("", "", "the directory holds more than one kustomization file")
587	}
588	
589	// readYAML reads a file of the overlay, within what is left of the ceilings.
590	func (g *gate) readYAML(file string) (*yaml.Node, string) {
591		data, reason := readGateFile(file, min(g.lim.FileBytes, g.lim.TotalBytes-g.read))
592		if reason != "" {
593			return nil, reason
594		}
595		g.read += int64(len(data))
596		return parseGateYAML(data)
597	}
598	
599	// clipLen is how many characters of a name from the repository a message keeps.
600	const clipLen = 200
601	
602	// clip is s cut to clipLen characters, with an ellipsis when it was longer: a
603	// field, a reference or a kind is the repository's own text, of any length.
604	func clip(s string) string {
605		if utf8.RuneCountInString(s) <= clipLen {
606			return s
607		}
608		return string([]rune(s)[:clipLen]) + "…"
609	}
610	
611	func join(prefix, name string) string {
612		if prefix == "" {
613			return name
614		}
615		return prefix + "." + name
616	}
617	
618	func isNull(n *yaml.Node) bool { return n.Kind == yaml.ScalarNode && n.Tag == "!!null" }
619	
620	// apply judges the value n of field by r.
621	func (g *gate) apply(r gateRule, n *yaml.Node, field string, s gateSite) gateVerdict {
622		if isNull(n) || r.kind == gateData {
623			return gateVerdict{}
624		}
625		switch r.kind {
626		case gateList:
627			return g.applyList(r, n, field, s)
628		case gateMap:
629			return g.applyMap(r, n, field, s, false)
630		case gateNever:
631			return g.applyNever(n, field, s)
632		case gatePatch:
633			if n.Kind == yaml.MappingNode { // inline, as data; kustomize rejects it
634				return gateVerdict{}
635			}
636		}
637		if n.Kind != yaml.ScalarNode || n.Tag != "!!str" {
638			return s.unchecked(field, "", "a reference that is not a string")
639		}
640		return g.applyString(r.kind, n.Value, field, s)
641	}
642	
643	func (g *gate) applyList(r gateRule, n *yaml.Node, field string, s gateSite) gateVerdict {
644		if n.Kind != yaml.SequenceNode {
645			return s.unchecked(field, "", "a value that is not a list")
646		}
647		for i, e := range n.Content {
648			if v := g.apply(*r.elem, e, fmt.Sprintf("%s[%d]", field, i), s); v.Kind != gateOK {
649				return v
650			}
651		}
652		return gateVerdict{}
653	}
654	
655	// applyMap judges the entries of a mapping. closed is the kustomization itself,
656	// where a field that kustomizationRules does not list is refused; elsewhere an
657	// entry no rule lists holds no reference.
658	func (g *gate) applyMap(r gateRule, n *yaml.Node, field string, s gateSite, closed bool) gateVerdict {
659		if n.Kind != yaml.MappingNode {
660			return s.unchecked(field, "", "a value that is not a mapping")
661		}
662		for i := 0; i+1 < len(n.Content); i += 2 {
663			key := n.Content[i].Value
664			sub, known := lookupRule(r.fields, key)
665			if !known && closed {
666				return s.unchecked(join(field, key), "", "a field that kustomize v5.8.3 does not have")
667			}
668			if !known {
669				continue
670			}
671			if v := g.apply(sub, n.Content[i+1], join(field, key), s); v.Kind != gateOK {
672				return v
673			}
674		}
675		return gateVerdict{}
676	}
677	
678	// applyNever refuses any value of a field that names a program to run or its
679	// arguments.
680	func (g *gate) applyNever(n *yaml.Node, field string, s gateSite) gateVerdict {
681		var parts []string
682		if n.Kind == yaml.ScalarNode {
683			parts = append(parts, n.Value)
684		}
685		for _, c := range n.Content {
686			parts = append(parts, c.Value)
687		}
688		ref := strings.Join(parts, " ")
689		if ref == "" {
690			return gateVerdict{}
691		}
692		return s.remote(field, ref, "it names a program to run or arguments for it")
693	}
694	
695	func (g *gate) applyString(kind gateRuleKind, value, field string, s gateSite) gateVerdict {
696		switch kind {
697		case gateFileSource:
698			parts := strings.Split(value, "=")
699			if len(parts) > 2 {
700				return s.unchecked(field, value, "a files entry with more than one equal sign")
701			}
702			return g.reference(parts[len(parts)-1], false, field, s)
703		case gatePlugin:
704			if strings.Contains(value, "\n") {
705				return g.inlinePlugin(value, field, s)
706			}
707			return g.pluginPath(value, field, s)
708		case gatePatch:
709			if strings.Contains(value, "\n") {
710				if inlineResources(value) {
711					return gateVerdict{}
712				}
713				return s.unchecked(field, "", "text that is neither a path nor a patch")
714			}
715			return g.reference(value, false, field, s)
716		}
717		return g.reference(value, kind == gateBase, field, s)
718	}
719	
720	// inlineResources reports whether text is what kustomize reads as an inline
721	// patch: documents that are Kubernetes objects.
722	func inlineResources(text string) bool {
723		dec := yaml.NewDecoder(strings.NewReader(text))
724		found := false
725		for {
726			var doc yaml.Node
727			err := dec.Decode(&doc)
728			if errors.Is(err, io.EOF) {
729				return found
730			}
731			if err != nil || doc.Kind != yaml.DocumentNode || len(doc.Content) != 1 || !hasKey(doc.Content[0], "kind") {
732				return false
733			}
734			found = true
735		}
736	}
737	
738	// hasKey reports whether n is a mapping with a key of exactly this name.
739	func hasKey(n *yaml.Node, name string) bool {
740		return mapGet(n, name) != nil
741	}
742	
743	// mapGet is the value of the key spelled exactly name in the mapping n.
744	func mapGet(n *yaml.Node, name string) *yaml.Node {
745		if n == nil || n.Kind != yaml.MappingNode {
746			return nil
747		}
748		for i := 0; i+1 < len(n.Content); i += 2 {
749			if n.Content[i].Value == name {
750				return n.Content[i+1]
751			}
752		}
753		return nil
754	}
755	
756	// reference judges one reference: it must be local, and below the limit once
757	// symbolic links are resolved. A directory is noted to be read in turn when
758	// follow says so.
759	func (g *gate) reference(ref string, follow bool, field string, s gateSite) gateVerdict {
760		real, found, v := g.resolve(ref, field, s)
761		if v.Kind != gateOK || !found {
762			return v
763		}
764		// Only a regular file or a directory: kustomize blocks on a pipe.
765		info, err := os.Stat(real)
766		switch {
767		case err != nil:
768			return s.unchecked(field, ref, "it cannot be read ("+errReason(err)+")")
769		case info.IsDir():
770			if follow {
771				g.bases = append(g.bases, real)
772			}
773		case !info.Mode().IsRegular():
774			return s.unchecked(field, ref, "it is neither a regular file nor a directory")
775		}
776		return gateVerdict{}
777	}
