804	// pluginPath judges an entry of generators, transformers or validators that is
805	// not inline: a plugin configuration file. A directory is refused, not followed:
806	// kustomize reads the resources of its kustomization as plugin configurations
807	// (and runs what they say), where the gate reads them as resources.
808	func (g *gate) pluginPath(ref, field string, s gateSite) gateVerdict {
809		real, found, v := g.resolve(ref, field, s)
810		if v.Kind != gateOK || !found {
811			return v
812		}
813		info, err := os.Stat(real)
814		switch {
815		case err != nil:
816			return s.unchecked(field, ref, "it cannot be read ("+errReason(err)+")")
817		case info.IsDir():
818			return s.unchecked(field, ref, "a plugin directory cannot be checked")
819		}
820		file := gateSite{file: g.rel(real), dir: s.dir, depth: s.depth}
821		node, reason := g.readYAML(real)
822		if reason != "" {
823			return file.unchecked("", "", reason)
824		}
825		return g.pluginConfig(node, "", file)
826	}
