837	// pluginConfig judges the configuration of a plugin: a builtin one of a known
838	// kind, that runs no function, whose fields that name a file are local.
839	func (g *gate) pluginConfig(node *yaml.Node, prefix string, s gateSite) gateVerdict {
840		scalar := func(name string) string {
841			if n := mapGet(node, name); n != nil && n.Kind == yaml.ScalarNode && n.Tag == "!!str" {
842				return n.Value
843			}
844			return ""
845		}
846		if version := scalar("apiVersion"); version != "builtin" {
847			return s.unchecked(join(prefix, "apiVersion"), "", fmt.Sprintf("a plugin of apiVersion %q: only builtin plugins are read", clip(version)))
848		}
849		kind := scalar("kind")
850		fields, known := builtinPlugins[kind]
851		if !known {
852			return s.unchecked(join(prefix, "kind"), "", fmt.Sprintf("a builtin plugin of kind %q, which the gate does not know", clip(kind)))
853		}
854		if annotations := mapGet(mapGet(node, "metadata"), "annotations"); annotations != nil && annotations.Kind == yaml.MappingNode {
855			for i := 0; i+1 < len(annotations.Content); i += 2 {
856				for _, name := range functionAnnotations {
857					if strings.EqualFold(annotations.Content[i].Value, name) {
858						return s.unchecked(join(prefix, "metadata.annotations"), "", "a function annotation, which makes kustomize run a program")
859					}
860				}
861			}
862		}
863		return g.apply(mapOf(fields), node, prefix, s)
864	}
