539		out, err := runner.Run(ctx, cmd, nil)
540		findings, recognised := parseHelmLint(out, chart, scope)
541		if err != nil && !recognised {
542			log.Printf("ERROR [scan/helm] lint %s: %v", logWord(chart), logErr(err))
