551	// parseHelmLint turns helm lint's text into findings. The second result says
552	// the output was helm lint's at all.
553	//
554	// A message's path is usually relative to the chart ("templates/cm.yaml"),
555	// but not always: the missing-dependency warning names the chart directory
556	// absolutely — "/scan/charts/broken" in a container, measured on helm 4.3.0.
557	// Both are brought back to a path relative to the target.
558	func parseHelmLint(out []byte, chart string, scope renderScope) ([]Finding, bool) {
559		file := func(p string) string { return helmLintPath(p, chart, scope) }
560		var findings []Finding
561		recognised := false
562		sc := bufio.NewScanner(bytes.NewReader(out))
563		for sc.Scan() {
564			line := strings.TrimSpace(sc.Text())
565			switch {
566			case strings.HasPrefix(line, "==> Linting"):
567				recognised = true
568			case strings.HasPrefix(line, "Error "):
569				// Printed instead of the messages when the chart could not be
570				// loaded at all.
571				recognised = true
572				findings = append(findings, helmLintFinding(chart, chart, SeverityHigh, strings.TrimPrefix(line, "Error ")))
573			default:
574				m := helmLintLine.FindStringSubmatch(line)
575				if m == nil {
576					continue
577				}
578				recognised = true
579				switch m[1] {
580				case "ERROR":
581					findings = append(findings, helmLintFinding(chart, file(m[2]), SeverityHigh, m[3]))
582				case "WARNING":
583					findings = append(findings, helmLintFinding(chart, file(m[2]), SeverityLow, m[3]))
584				}
585			}
586		}
587		return findings, recognised
588	}
