590	// helmLintPath resolves a path helm lint printed to one relative to the
591	// target. In a container the target is the scope's working directory, which is
592	// /scan itself unless the git repository around the target is mounted.
593	func helmLintPath(p, chart string, scope renderScope) string {
594		p = strings.TrimSuffix(p, "/")
595		switch {
596		case p == containerScanPath || strings.HasPrefix(p, containerScanPath+"/"):
597			if rel, err := filepath.Rel(filepath.FromSlash(scope.workdir()), filepath.FromSlash(p)); err == nil {
598				return filepath.ToSlash(rel)
599			}
600			return p
601		case filepath.IsAbs(p):
602			if rel, err := filepath.Rel(scope.target, p); err == nil && !strings.HasPrefix(rel, "..") {
603				return filepath.ToSlash(rel)
604			}
605			return filepath.ToSlash(p)
606		default:
607			return path.Join(chart, p)
608		}
609	}
